const source = $json;

function header(name) {
  const direct = source[name] ?? source[name.toLowerCase()] ?? source[name.toUpperCase()];
  if (typeof direct === 'string') return direct;
  const headers = source.headers ?? source.payload?.headers ?? [];
  if (Array.isArray(headers)) {
    const found = headers.find(h => String(h?.name ?? '').toLowerCase() === name.toLowerCase());
    if (found && typeof found.value === 'string') return found.value;
  }
  return '';
}

function mailbox(value) {
  const angle = String(value ?? '').match(/<\s*([^<>\s]+@[^<>\s]+)\s*>/);
  const raw = angle?.[1] ?? String(value ?? '').match(/\b([^\s<>]+@[^\s<>]+)\b/)?.[1] ?? '';
  return raw.trim().toLowerCase();
}

const from = header('From');
const sender = mailbox(from);
const domain = sender.includes('@') ? sender.split('@').pop() : '';
const validSender = domain === 'fiverr.com' || domain.endsWith('.fiverr.com');
const subject = header('Subject');
const text = [source.text, source.textPlain, source.snippet, source.body, source.payload?.body?.data]
  .filter(v => typeof v === 'string' && v.trim())
  .join('\n')
  .slice(0, 50000);
const receivedRaw = source.internalDate ?? source.date ?? source.Date ?? null;
let receivedAt = null;
if (receivedRaw) {
  const numeric = Number(receivedRaw);
  const parsed = Number.isFinite(numeric) && numeric > 100000000000 ? new Date(numeric) : new Date(receivedRaw);
  if (!Number.isNaN(parsed.getTime())) receivedAt = parsed.toISOString();
}

return [{
  json: {
    valid_sender: validSender,
    sender_domain: domain,
    payload: {
      message_id: String(source.id ?? source.messageId ?? source.message_id ?? ''),
      thread_id: source.threadId ?? source.thread_id ?? null,
      from,
      subject: String(subject ?? '').slice(0, 500),
      snippet: String(source.snippet ?? '').slice(0, 5000),
      text,
      received_at: receivedAt,
      labels: Array.isArray(source.labelIds) ? source.labelIds.map(String).slice(0,100) : []
    }
  }
}];

const response = $json;
if (!response?.ok || !response?.event) throw new Error('AMS Fiverr intake rejected the notification');
const event = response.event;
const brief = response.operator_brief ?? {};
const order = event.order_reference ?? 'not detected';
const buyer = event.buyer_username ?? 'not detected';
const deadline = event.deadline_at ?? event.deadline_hint ?? 'not detected';
const service = event.service_slug ?? 'manual review';
const deliverables = Array.isArray(brief.fulfillment?.deliverables) ? brief.fulfillment.deliverables.map(v => `- ${v}`).join('\n') : '- No automated deliverable package selected';
const prohibited = Array.isArray(brief.prohibited_actions) ? brief.prohibited_actions.map(v => `- ${v}`).join('\n') : '';

const approvalMessage = [
  'AMS FIVERR BRIDGE — HUMAN REVIEW REQUIRED',
  '',
  `Event: ${event.event_type}`,
  `Priority: ${event.priority}`,
  `Order: ${order}`,
  `Buyer: ${buyer}`,
  `Deadline: ${deadline}`,
  `Service: ${service}`,
  `Recommended internal action: ${event.recommended_action}`,
  '',
  'Planned deliverables:',
  deliverables,
  '',
  'Safety boundary:',
  prohibited,
  '',
  'Open Fiverr manually to take any buyer-facing action. Nothing in this workflow can send, accept, cancel, revise, or deliver on Fiverr.',
  '',
  'Sanitized Fiverr context:',
  String(event.safe_context ?? '').slice(0, 5000)
].join('\n');

return [{ json: {
  event_id: event.event_id,
  event_type: event.event_type,
  order_reference: event.order_reference,
  buyer_username: event.buyer_username,
  deadline_at: event.deadline_at,
  service_slug: event.service_slug,
  subject: `AMS Fiverr review | ${event.event_type} | ${order}`,
  approval_message: approvalMessage
} }];
